 "content": "def transform(grid):
    """Project aligned colored markers across the 5x5 tiled lattice."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in g[r])]
    sep_cols = [c for c in range(w) if all(g[r][c] == 8 for r in range(h))]

    def complete_spans(length, separators):
        # Each separator closes a full tile; a possible trailing fragment is padding.
        spans = []
        start = 0
        for s in separators:
            if s > start:
                spans.append((start, s))
            start = s + 1
        return spans

    row_spans = complete_spans(h, sep_rows)
    col_spans = complete_spans(w, sep_cols)
    # The final run after the last separator is a cropped padding strip, not a tile.
    nr, nc = len(row_spans), len(col_spans)
    row_spans = row_spans[:5]
    col_spans = col_spans[:5]

    markers = {2: [], 3: []}
    for i, (r0, r1) in enumerate(row_spans):
        for j, (c0, c1) in enumerate(col_spans):
            found = {g[r][c] for r in range(r0, r1) for c in range(c0, c1) if g[r][c] in (2, 3)}
            for color in found:
                markers[color].append((i, j))

    fill = [[0 for _ in col_spans] for _ in row_spans]
    for color, points in markers.items():
        rows = {}
        cols = {}
        for i, j in points:
            rows.setdefault(i, set()).add(j)
            cols.setdefault(j, set()).add(i)
        for i, js in rows.items():
            if len(js) >= 2:
                for j in range(len(col_spans)):
                    fill[i][j] = color if fill[i][j] == 0 else 6
        for j, iset in cols.items():
            if len(iset) >= 2:
                for i in range(len(row_spans)):
                    fill[i][j] = color if fill[i][j] == 0 else 6

    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in sep_rows:
        out[r] = [8] * w
    for c in sep_cols:
        for r in range(h):
            out[r][c] = 8
    for i, (r0, r1) in enumerate(row_spans):
        for j, (c0, c1) in enumerate(col_spans):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = fill[i][j]
    return out

if __name__ == '__main__':
